  3	const fs = require('fs');
  4	const path = require('path');
  5	const yaml = require('js-yaml');
  6	
  7	class ConfigManager {
  8	  constructor(configPath) {
  9	    this.configPath = configPath;
 10	    // 所有持久化文件统一放在 configPath 同级目录下
 11	    this.configDir = path.dirname(configPath);
 12	    this.statsPath = path.join(this.configDir, 'stats.json');
 13	
 14	    this.channels = {};
 15	    this.modelRouting = {};
 16	    this.defaultRouting = { channel: '', model: null };
 17	    this.server = { port: 10204, host: '0.0.0.0' };
 18	    this.logLevel = 'INFO';
 19	    this.stats = { totalRequests: 0, totalErrors: 0, startTime: Date.now() };
 20	
 21	    // 确保配置目录存在
 22	    this._ensureDir();
 23	  }
 24	
 25	  _ensureDir() {
 26	    if (!fs.existsSync(this.configDir)) {
 27	      fs.mkdirSync(this.configDir, { recursive: true });
 28	    }
 29	  }
 30	
 31	  load() {
 32	    if (!fs.existsSync(this.configPath)) {
 33	      this._createDefault();
 34	    }
 35	    const raw = fs.readFileSync(this.configPath, 'utf8');
 36	    const data = yaml.load(raw) || {};
 37	    this.server = { ...this.server, ...data.server };
 38	    this.channels = data.channels || {};
 39	    this.modelRouting = {};
 40	    this.defaultRouting = { channel: '', model: null };
 41	    const routing = data.model_routing || {};
 42	    for (const [key, val] of Object.entries(routing)) {
 43	      if (key === '_default') {
 44	        this.defaultRouting = val;
 45	      } else {
 46	        this.modelRouting[key] = val;
 47	      }
 48	    }
 49	    this.logLevel = data.log_level || 'INFO';
 50	
 51	    // 加载持久化的 stats 数据
 52	    this._loadStats();
 53	  }
 54	
 55	  // 启动文件监控：配置文件被外部修改后自动重新加载
 56	  startWatch() {
 57	    if (this._watcher) return;
 58	    this._saving = false;
 59	    this._watchTimer = null;
 60	    try {
 61	      this._watcher = fs.watch(this.configPath, (eventType) => {
 62	        if (eventType !== 'change') return;
 63	        // 正在保存中，忽略自身写入触发的事件
 64	        if (this._saving) return;
 65	        // 防抖：连续写入只触发一次重载
 66	        if (this._watchTimer) clearTimeout(this._watchTimer);
 67	        this._watchTimer = setTimeout(() => {
 68	          try {
 69	            const oldLogLevel = this.logLevel;
 70	            this.load();
 71	            if (this._onReload) this._onReload();
 72	          } catch (e) {
 73	            console.error('[CONFIG] 自动重载配置失败:', e.message);
 74	          }
 75	        }, 500);
 76	      });
 77	    } catch (e) {
 78	      console.warn('[CONFIG] 无法启动文件监控:', e.message);
 79	    }
 80	  }
 81	
 82	  stopWatch() {
 83	    if (this._watcher) { this._watcher.close(); this._watcher = null; }
 84	  }
 85	
 86	  onReload(cb) { this._onReload = cb; }
 87	
 88	  save() {
 89	    this._saving = true;
 90	    try {
 91	      const routing = { ...this.modelRouting, _default: this.defaultRouting };
 92	      const data = {
 93	        server: this.server,
 94	        channels: this.channels,
 95	        model_routing: routing,
 96	        log_level: this.logLevel,
 97	      };
 98	      // 使用原子写入：先写临时文件，再重命名替换，避免 Windows 上的 EPERM 错误
 99	      const tmpPath = this.configPath + '.tmp.' + Date.now();
100	      fs.writeFileSync(tmpPath, yaml.dump(data, { indent: 2, lineWidth: 120 }), 'utf8');
101	      try {
102	        fs.renameSync(tmpPath, this.configPath);
103	      } catch (e) {
104	        try { fs.unlinkSync(this.configPath); } catch (_) {}
105	        fs.renameSync(tmpPath, this.configPath);
106	      }
107	    } finally {
108	      this._saving = false;
109	    }
110	  }
111	
112	  _createDefault() {
113	    const emptyConfig = {
114	      server: { port: 10204, host: '0.0.0.0' },
115	      channels: {},
116	      model_routing: { _default: { channel: '', model: null } },
117	      log_level: 'INFO',
118	    };
119	    // 使用原子写入避免 Windows EPERM 错误
120	    const tmpPath = this.configPath + '.tmp.' + Date.now();
121	    fs.writeFileSync(tmpPath, yaml.dump(emptyConfig, { indent: 2 }), 'utf8');
122	    try {
123	      fs.renameSync(tmpPath, this.configPath);
124	    } catch (e) {
125	      try { fs.unlinkSync(this.configPath); } catch (_) {}
126	      fs.renameSync(tmpPath, this.configPath);
127	    }
128	  }
129	
130	  // ---- 持久化 stats ----
131	
132	  _loadStats() {
133	    try {
134	      if (fs.existsSync(this.statsPath)) {
135	        const raw = fs.readFileSync(this.statsPath, 'utf8');
136	        const saved = JSON.parse(raw) || {};
137	        this.stats.totalRequests = saved.totalRequests || 0;
138	        this.stats.totalErrors = saved.totalErrors || 0;
139	        // startTime 使用本次启动时间
140	        this.stats.startTime = Date.now();
141	      }
142	    } catch (e) {
143	      console.warn('[CONFIG] 加载 stats 数据失败:', e.message);
144	    }
145	  }
146	
147	  _saveStats() {
148	    try {
149	      const tmpPath = this.statsPath + '.tmp.' + Date.now();
150	      fs.writeFileSync(tmpPath, JSON.stringify({
151	        totalRequests: this.stats.totalRequests,
152	        totalErrors: this.stats.totalErrors,
153	      }, null, 2), 'utf8');
154	      try { fs.renameSync(tmpPath, this.statsPath); } catch (e) {
155	        try { fs.unlinkSync(this.statsPath); } catch (_) {}
156	        fs.renameSync(tmpPath, this.statsPath);
157	      }
158	    } catch (e) {
159	      console.warn('[CONFIG] 保存 stats 数据失败:', e.message);
160	    }
161	  }
162	
163	  // ---- 渠道 CRUD ----
164	
165	  getChannelList() {
166	    return Object.entries(this.channels).map(([name, cfg]) => ({
167	      name,
168	      base_url: cfg.base_url || '',
169	      api_key: cfg.api_key || '',
