281	  // ---- 模型路由解析（五层优先级） ----
282	  // 1. 显式路由表 → 指定渠道 + 实际模型名
283	  // 2. 渠道可用模型列表 + 权重分发 → 多个渠道声明同名模型时按权重随机选择
284	  // 3. 默认渠道 → 原样透传模型名
285	  // 4. 单渠道兜底 → 仅有一个渠道时自动使用该渠道
286	
287	  resolveModel(requestModel) {
288	    // 优先级1：显式路由表
289	    const explicitRoute = this.modelRouting[requestModel];
290	    if (explicitRoute) {
291	      const channelCfg = this.channels[explicitRoute.channel];
292	      if (!channelCfg) {
293	        return {
294	          error: true,
295	          status: 503,
296	          message: '路由指向的渠道不存在: ' + explicitRoute.channel,
297	          type: 'routing_error',
298	        };
299	      }
300	      return {
301	        channelName: explicitRoute.channel,
302	        channelConfig: channelCfg,
303	        actualModel: explicitRoute.model || requestModel,
304	        originalModel: requestModel,
305	        matchedBy: 'routing',
306	      };
307	    }
308	
309	    // 优先级2：渠道可用模型列表 + 权重分发
310	    // 收集所有声明了该模型的渠道，按权重进行加权随机选择
311	    const modelCandidates = [];
312	    for (const [chName, chCfg] of Object.entries(this.channels)) {
313	      const models = chCfg.models || [];
314	      if (models.includes(requestModel)) {
315	        modelCandidates.push({
316	          name: chName,
317	          config: chCfg,
318	          weight: chCfg.weight || 1,
319	        });
320	      }
321	    }
322	    if (modelCandidates.length > 0) {
323	      const selected = this._weightedSelect(modelCandidates);
324	      return {
325	        channelName: selected.name,
326	        channelConfig: selected.config,
327	        actualModel: requestModel,
328	        originalModel: requestModel,
329	        matchedBy: 'models_weighted',
330	        selectedWeight: selected.weight,
331	        candidatesCount: modelCandidates.length,
332	      };
333	    }
334	
335	    // 优先级3：默认渠道
336	    const defaultChannel = this.defaultRouting.channel;
337	    if (defaultChannel) {
338	      const channelCfg = this.channels[defaultChannel];
339	      if (!channelCfg) {
340	        return {
341	          error: true,
342	          status: 503,
343	          message: '默认渠道不存在: ' + defaultChannel,
344	          type: 'routing_error',
345	        };
346	      }
347	      return {
348	        channelName: defaultChannel,
349	        channelConfig: channelCfg,
350	        actualModel: this.defaultRouting.model || requestModel,
351	        originalModel: requestModel,
352	        matchedBy: 'default',
353	      };
354	    }
355	
356	    // 优先级4：单渠道兜底（仅配置了唯一渠道时自动使用）
357	    const channelNames = Object.keys(this.channels);
358	    if (channelNames.length === 1) {
359	      const soleChannelName = channelNames[0];
360	      const soleChannelCfg = this.channels[soleChannelName];
361	      return {
362	        channelName: soleChannelName,
363	        channelConfig: soleChannelCfg,
364	        actualModel: requestModel,
365	        originalModel: requestModel,
366	        matchedBy: 'single_channel_fallback',
367	      };
368	    }
369	
370	    // 无任何渠道配置
371	    if (channelNames.length === 0) {
372	      return {
373	        error: true,
374	        status: 503,
375	        message: '尚未配置任何渠道，请先在管理面板添加渠道',
376	        type: 'no_channel',
377	      };
378	    }
379	
380	    // 多渠道但无匹配
381	    return {
382	      error: true,
383	      status: 404,
384	      message: '模型 "' + requestModel + '" 无法路由：未在路由表中、未在任何渠道的可用模型列表中、也未设置默认渠道。请配置路由规则或设置默认渠道。',
385	      type: 'model_not_found',
386	      code: 'model_not_found',
387	    };
388	  }
389	
390	  // ---- 加权随机选择：根据权重从候选中选取一个渠道 ----
391	  // 权重越高，被选中的概率越大；所有候选权重均为 0 时则均等随机
392	
393	  _weightedSelect(candidates) {
394	    const totalWeight = candidates.reduce((sum, c) => sum + c.weight, 0);
395	    if (totalWeight <= 0) {
396	      // 所有权重为 0，均等随机
397	      return candidates[Math.floor(Math.random() * candidates.length)];
398	    }
399	    let random = Math.random() * totalWeight;
400	    for (const c of candidates) {
401	      random -= c.weight;
402	      if (random <= 0) return c;
403	    }
404	    return candidates[candidates.length - 1];
405	  }
