407	  // ---- 获取所有可用模型名（用于 /v1/models） ----
408	
409	  getAvailableModels() {
410	    const models = [];
411	    // 路由表中的模型（别名）
412	    for (const [alias, route] of Object.entries(this.modelRouting)) {
413	      models.push({ id: alias, channel: route.channel, type: 'routing' });
414	    }
415	    // 渠道声明可用模型（原样透传）
416	    for (const [chName, chCfg] of Object.entries(this.channels)) {
417	      for (const m of (chCfg.models || [])) {
418	        if (!models.find(x => x.id === m)) {
419	          models.push({ id: m, channel: chName, type: 'models' });
420	        }
421	      }
422	    }
423	    // 如果是单渠道兜底，则该渠道的 models 列表也加入（即使没有路由）
424	    if (Object.keys(this.channels).length === 1 && models.length === 0) {
425	      const soleChannel = Object.keys(this.channels)[0];
426	      for (const m of (this.channels[soleChannel].models || [])) {
427	        models.push({ id: m, channel: soleChannel, type: 'models' });
428	      }
429	    }
430	    return models;
431	  }
