282	    logger.info('→ 路由 ' + originalModel + ' → ' + channelName + '/' + actualModel, {
283	      req: reqId, channel: channelName,
284	      actualModel: actualModel,
285	      matchedBy: matchedBy,
286	    });
287	
288	    // 转换请求
289	    let ccReq;
290	    try {
291	      ccReq = responsesToChatCompletions(reqBody, actualModel);
292	      normalizeChatRequest(ccReq, provider);
293	    } catch (e) {
294	      config.recordError();
295	      logger.error('← 请求转换失败', { req: reqId, error: e.message });
296	      return res.status(400).json({
297	        error: {
298	          message: e.message,
299	          type: 'conversion_error',
300	          code: 'invalid_request_error',
301	        }
302	      });
303	    }
304	
305	    const headers = buildUpstreamHeaders(channelConfig);
306	    const upstreamUrl = (channelConfig.base_url || '').replace(/\/+$/, '') + '/v1/chat/completions';
307	    const timeoutMs = (channelConfig.timeout || 300) * 1000;
308	
309	    const upstreamBody = {
310	      model: ccReq.model,
311	      messages: ccReq.messages.length + '条',
312	      max_tokens: ccReq.max_tokens,
313	      tools: ccReq.tools ? ccReq.tools.length + '个' : undefined,
314	      stream: ccReq.stream || false,
315	    };
316	    logger.debug('→ 上游请求', { req: reqId, url: upstreamUrl, body: JSON.stringify(upstreamBody) });
317	
318	    try {
319	      if (isStream) {
320	        // ---- 流式 ----
321	        const upstreamResp = await fetch(upstreamUrl, {
322	          method: 'POST',
323	          headers: { ...headers, 'Content-Type': 'application/json' },
324	          body: JSON.stringify(ccReq),
325	          signal: AbortSignal.timeout(timeoutMs),
326	        });
327	
328	        if (!upstreamResp.ok) {
329	          config.recordError();
330	          let errorText = await upstreamResp.text();
331	          logger.warn('← 上游错误 ' + upstreamResp.status, { req: reqId, body: errorText.slice(0, 200) });
332	          res.writeHead(upstreamResp.status, { 'Content-Type': 'application/json' });
333	          res.end(errorText);
334	          return;
335	        }
336	
337	        logger.info('→ 流式响应开始', { req: reqId });
338	        res.writeHead(200, {
339	          'Content-Type': 'text/event-stream',
340	          'Cache-Control': 'no-cache',
341	          'Connection': 'keep-alive',
342	          'X-Accel-Buffering': 'no',
343	        });
344	
345	        const respId = genId('resp_');
346	        await convertStream(upstreamResp, res, respId, originalModel, logger, reqBody, provider);
347	        logger.info('← 流式响应完成', { req: reqId, respId });
348	        // 确保所有 SSE 事件已刷新到 TCP 缓冲区再关闭连接，
349	        // 避免客户端在收到最后一个 event 前检测到 FIN
350	        await new Promise(resolve => setTimeout(resolve, 300));
351	        res.end();
352	      } else {
353	        // ---- 非流式 ----
354	        const upstreamResp = await fetch(upstreamUrl, {
355	          method: 'POST',
356	          headers: { ...headers, 'Content-Type': 'application/json' },
357	          body: JSON.stringify(ccReq),
358	          signal: AbortSignal.timeout(timeoutMs),
359	        });
360	
361	        if (!upstreamResp.ok) {
362	          config.recordError();
363	          let errorText = await upstreamResp.text();
364	          logger.warn('← 上游错误 ' + upstreamResp.status, { req: reqId, body: errorText.slice(0, 200) });
365	          res.writeHead(upstreamResp.status, { 'Content-Type': 'application/json' });
366	          res.end(errorText);
367	          return;
368	        }
369	
370	        const ccResp = await upstreamResp.json();
371	        normalizeChatResponse(ccResp, provider);
372	        const respObj = chatCompletionsToResponses(ccResp, originalModel);
373	
374	        const outputTypes = (respObj.output || []).map(o => o.type);
375	        logger.info('← 响应完成', {
376	          req: reqId,
377	          output: outputTypes,
378	          input_tokens: respObj.usage.input_tokens,
379	          output_tokens: respObj.usage.output_tokens,
380	          status: respObj.status,
381	        });
382	
383	        res.json(respObj);
384	      }
385	    } catch (e) {
386	      config.recordError();
387	      logger.error('← 请求转发异常', { req: reqId, error: e.message });
388	      console.error('[PROXY] 请求转发异常:', e.message);
389	      if (!res.headersSent) {
390	        res.status(500).json({
391	          error: {
392	            message: e.message,
393	            type: 'proxy_error',
394	            code: 'internal_error',
395	          }
396	        });
397	      } else {
398	        res.end();
399	      }
400	    }
401	  });
402	
403	  // ============================================================
404	  // GET /v1/models（返回所有可用模型：路由别名 + 渠道模型）
405	  // ============================================================
406	  app.get('/v1/models', (req, res) => {
407	    const models = config.getAvailableModels().map(m => ({
408	      id: m.id, object: 'model', created: Math.floor(Date.now() / 1000), owned_by: m.channel,
409	    }));
410	    res.json({ object: 'list', data: models });
411	  });
412	
413	  return { app, config };
414	}
415	
