{"path": "scripts/validate_project.py", "content": "#!/usr/bin/env python3
"""校验项目结构是否合规。"""

import argparse
import sys
from pathlib import Path

from utils.helpers import list_projects, list_tasks, project_dir, workspace_root
from validate_task import validate_task


REQUIRED_PROJECT_FILES = ["config.toml", "README.md"]
REQUIRED_PROJECT_DIRS = ["tasks"]


def check_project_structure(project_id: str) -> list[str]:
    errors = []
    pd = project_dir(project_id)
    for name in REQUIRED_PROJECT_FILES:
        if not (pd / name).exists():
            errors.append(f"项目缺少文件: {name}")
    for name in REQUIRED_PROJECT_DIRS:
        if not (pd / name).is_dir():
            errors.append(f"项目缺少目录: {name}")
    return errors


def validate_project(project_id: str) -> dict:
    result = {
        "project": project_id,
        "ok": True,
        "errors": [],
        "tasks": [],
    }
    result["errors"].extend(check_project_structure(project_id))

    for task_dir in list_tasks(project_id):
        task_result = validate_task(task_dir)
        result["tasks"].append(task_result)
        if not task_result["ok"]:
            result["ok"] = False

    if result["errors"]:
        result["ok"] = False

    return result


def main():
    parser = argparse.ArgumentParser(description="校验项目结构")
    parser.add_argument("--project", help="指定项目 ID")
    parser.add_argument("--all", action="store_true", help="校验所有项目")
    args = parser.parse_args()

    if args.all:
        projects = [p.name for p in list_projects()]
    elif args.project:
        projects = [args.project]
    else:
        print("请指定 --project 或 --all")
        sys.exit(1)

    all_ok = True
    for project_id in projects:
        result = validate_project(project_id)
        status = "✅ 通过" if result["ok"] else "❌ 失败"
        print(f"\n{status} 项目: {result['project']}")
        for err in result["errors"]:
            print(f"  - {err}")
        for task_result in result["tasks"]:
            task_status = "✅ 通过" if task_result["ok"] else "❌ 失败"
            print(f"  {task_status} 任务: {task_result['task']}")
            for err in task_result["errors"]:
                print(f"    - {err}")
        if not result["ok"]:
            all_ok = False

    sys.exit(0 if all_ok else 1)


if __name__ == "__main__":
    main()
"}

