REQUIRED_DIRS = ["starter", "assets", "mock-data", "tests", "screenshots"]


def check_structure(task_dir: Path) -> list[str]:
    errors = []
    for name in REQUIRED_FILES:
        if not (task_dir / name).exists():
            errors.append(f"缺少文件: {name}")
    for name in REQUIRED_DIRS:
        if not (task_dir / name).is_dir():
            errors.append(f"缺少目录: {name}")
    return errors


def check_metadata(task_dir: Path) -> list[str]:
    errors = []
    try:
        metadata = load_json(task_dir / "metadata.json")
    except Exception as e:
        return [f"metadata.json 解析失败: {e}"]

    required_keys = ["task_id", "title", "category_tags", "arena_tags", "prompt_type", "difficulty", "status"]
    for key in required_keys:
        if key not in metadata:
            errors.append(f"metadata.json 缺少字段: {key}")

    categories_path = workspace_root() / "config" / "categories.json"
    if categories_path.exists():
        categories = load_json(categories_path)
        valid_categories = {c["label"] for c in categories.get("category_tree", [])}
        for cat in metadata.get("category_tags", []):
            if cat not in valid_categories:
                errors.append(f"非法 category_tags: {cat}")

        valid_arena = set(categories.get("arena_tags", []))
        for tag in metadata.get("arena_tags", []):
            if tag not in valid_arena:
                errors.append(f"非法 arena_tags: {tag}")

    return errors


def check_rubric(task_dir: Path) -> list[str]:
    errors = []
    try:
        rubric = load_json(task_dir / "rubric.json")
    except Exception as e:
        return [f"rubric.json 解析失败: {e}"]

    dimensions = rubric.get("dimensions", [])
    if not dimensions:
        errors.append("rubric.json 缺少 dimensions")
        return errors

    total_weight = 0.0
    leaf_count = 0
    for dim in dimensions:
        for leaf in dim.get("leaves", []):
            leaf_count += 1
            total_weight += leaf.get("weight", 0)
            if not leaf.get("grader_spec"):
                errors.append(f"Rubric 叶节点缺少 grader_spec: {leaf.get('id')}")
            if not leaf.get("evidence_required"):
                errors.append(f"Rubric 叶节点缺少 evidence_required: {leaf.get('id')}")

    if leaf_count < 10:
        errors.append(f"Rubric 叶节点数量不足: {leaf_count} < 10")
    if leaf_count > 20:
        errors.append(f"Rubric 叶节点数量过多: {leaf_count} > 20")
    if abs(total_weight - 1.0) > 0.001:
        errors.append(f"Rubric 权重之和不等于 1.0: {total_weight}")

    return errors


def check_starter(task_dir: Path) -> list[str]:
    errors = []
    starter = task_dir / "starter"
    if not starter.exists():
        return errors

    if not (starter / "package.json").exists():
        errors.append("starter/ 缺少 package.json")

    has_lockfile = any(
        (starter / name).exists()
        for name in ["package-lock.json", "pnpm-lock.yaml", "yarn.lock"]
    )
    if not has_lockfile:
        errors.append("starter/ 缺少 lockfile")

    return errors


def validate_task(task_dir: Path) -> dict:
    result = {
        "task": task_dir.name,
        "ok": True,
        "errors": [],
    }
    result["errors"].extend(check_structure(task_dir))
    result["errors"].extend(check_metadata(task_dir))
    result["errors"].extend(check_rubric(task_dir))
    result["errors"].extend(check_starter(task_dir))
    result["ok"] = len(result["errors"]) == 0
    return result


def main():
    parser = argparse.ArgumentParser(description="校验 Web Dev 任务")
    parser.add_argument("--project", help="指定项目 ID")
    parser.add_argument("--task", help="指定任务目录或 ID")
    parser.add_argument("--all", action="store_true", help="校验所有项目中的所有任务")
    parser.add_argument("--gate", help="指定闸门（runnability/completeness/visual/rubric/solvability/contamination）")
    args = parser.parse_args()

    if args.all:
        from utils.helpers import list_projects
        all_ok = True
        for project in list_projects():
            for task_dir in list_tasks(project.name):
                result = validate_task(task_dir)
                status = "✅ 通过" if result["ok"] else "❌ 失败"
                print(f"\n{status} {project.name}/{result['task']}")
                for err in result["errors"]:
                    print(f"  - {err}")
                if not result["ok"]:
                    all_ok = False
        sys.exit(0 if all_ok else 1)

    if args.task:
        task_path = Path(args.task)
        if not task_path.is_absolute():
            if args.project:
                task_path = tasks_dir(args.project) / task_path.name
            else:
                task_path = workspace_root() / "tasks" / task_path.name
        task_dirs = [task_path]
    elif args.project:
        task_dirs = list_tasks(args.project)
    else:
        print("请指定 --project、--task 或 --all")
        sys.exit(1)

    all_ok = True
    for task_dir in task_dirs:
        result = validate_task(task_dir)
        status = "✅ 通过" if result["ok"] else "❌ 失败"
        print(f"\n{status} {result['task']}")
        for err in result["errors"]:
            print(f"  - {err}")
        if not result["ok"]:
            all_ok = False

    sys.exit(0 if all_ok else 1)


if __name__ == "__main__":
    main()
"}

